"""Build the portable local storyboard from the shipped manifest and measured telemetry."""
import html, json
from pathlib import Path
root=Path(__file__).resolve().parents[2]
out=root/'docs/brushline/showcase'
film=json.loads((root/'resources/showcase/film.json').read_text())
metrics=json.loads((out/'validation/metrics.json').read_text())
titles=['秋色中发现赛车','低位追拍 · 冰青光柱','固定侧拍 · 制动准备','连续外甩、反打与救回','驯鹿横穿 · 赛车随后驶过','海湾与沿岸公路','引擎盖视角 · 连续弯道','770 m 河桥 · 两岸关系','新闻直升机伴飞','暮色悬崖公路','车灯与琥珀光柱','拉远、抬升、淡出']
descriptions=['高位斜俯，下降中交代道路、秋色和山峦。','低位后三分之四机位，真实轮胎与路肩视差。','固定道路右侧，不随车身横摆左右换边。','12 秒不切镜；机位朝向平滑道路切线，保留车身与速度方向的夹角。','驯鹿先横穿、离开道路，车辆随后从近处驶过；保守车身包络留有 3.03 秒间隔。','朝向海湾取景，纳入海面、帆船与道路走向。','保留录制中的真实车身运动；不添加震屏，车头位于画面下方。','河道、桥面与两岸先建立空间关系，F160 完整通过。','独立外部机位；直升机与车辆同框，旋翼和摄影位可辨。','从谷地一侧看山壁、道路、谷地和远山。','暮色中依靠头灯、路面纹理及轮胎运动表现速度。','赛车继续前进；74.4 秒开始淡出，75 秒到结束页。']
cards=[]; rows=[]
for i,(s,m) in enumerate(zip(film['shots'],metrics['shots'])):
    car='R200' if i<5 else ('F160' if i<9 else 'A240')
    stage='夕照松岭' if i<5 else ('晴岬海岸' if i<9 else '雾杉高地')
    clock=f'{s["start"]:02d}–{s["start"]+s["duration"]:02d} s'
    image=f'previews/{i+1:02d}-{s["id"]}.jpg'
    cards.append(f'''<article class="shot"><button class="still" data-seek="{s['start']}" aria-label="播放第 {i+1} 镜"><img src="{image}" alt="{html.escape(titles[i])}" loading="lazy"><span>{clock}</span></button><div class="copy"><small>{stage} / {car}</small><h3>{i+1:02d}　{titles[i]}</h3><p>{descriptions[i]}</p><p class="speed">实测中位 {m['speed_kph_median']:.1f} km/h <span>范围 {m['speed_kph_min']:.1f}–{m['speed_kph_max']:.1f}</span></p><details><summary>素材与机位</summary><p>{s['clip']}.json · {s['source_in']:g}–{s['source_in']+s['duration']:g} 秒<br>轨道：{s['camera_rail']}<br>事件：{', '.join(s['events']) or '环境与车辆'}</p></details></div></article>''')
    rows.append(f'<tr><td>{clock}</td><td>{titles[i]}</td><td>{m["speed_kph_min"]:.1f}</td><td>{m["speed_kph_median"]:.1f}</td><td>{m["speed_kph_max"]:.1f}</td></tr>')
hero=metrics['recovery']
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>75 秒 Demo · 分镜与实机交付</title><style>
:root{color-scheme:dark;--paper:#f3ead2;--muted:#b1bbb4;--line:#3c4946;--gold:#ffc46b}*{box-sizing:border-box}body{margin:0;background:#142321;color:var(--paper);font:16px/1.65 system-ui,-apple-system,"PingFang SC",sans-serif}main{max-width:1280px;margin:auto;padding:44px 28px}a{color:#8bdfe6}h1{font-size:clamp(32px,5vw,64px);line-height:1.1;margin:14px 0}h2{font-size:27px;margin-top:48px}h3{margin:8px 0;font-size:21px}small,.muted{color:var(--muted)}.lead{max-width:850px;color:#d1d8d0;font-size:19px}.eyebrow{letter-spacing:.16em;font-size:12px;color:var(--gold)}video{width:100%;background:#000;border:1px solid var(--line);border-radius:8px}.stats{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}.stat{background:#243532;border:1px solid var(--line);border-radius:6px;padding:12px 20px}.stat b{display:block;font-size:25px;color:var(--gold)}.stat span{font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.shot{overflow:hidden;border:1px solid var(--line);border-radius:7px;background:#1b2d2a}.still{position:relative;display:block;border:0;padding:0;width:100%;background:#000;cursor:pointer}.still img{display:block;width:100%;aspect-ratio:16/9}.still span{position:absolute;left:14px;bottom:12px;background:#10211fde;color:white;padding:4px 10px;border-radius:4px}.copy{padding:18px 22px}.copy p{margin:12px 0}.speed{color:#a2e0db;font-size:14px}.speed span{display:block;color:var(--muted)}summary{cursor:pointer;color:var(--gold)}details{margin:15px 0}details p{color:var(--muted);font-size:14px}.links{display:flex;gap:18px;flex-wrap:wrap}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:9px;text-align:left;border-bottom:1px solid var(--line)}.note{border-left:3px solid var(--gold);padding:12px 20px;background:#28342c}button:focus-visible,a:focus-visible{outline:3px solid var(--gold);outline-offset:3px}footer{margin-top:45px;color:var(--muted);font-size:13px}@media(max-width:720px){main{padding:26px 16px}.grid{grid-template-columns:1fr}.stat{flex:1;min-width:140px}.copy{padding:16px}h2{margin-top:32px}}
</style><main><div class="eyebrow">BRUSHLINE RALLY / CINEMATIC DEMO / 2026.10.21</div><h1>速度、救车与沿途风景</h1><p class="lead">75 秒，三条赛道，三辆原厂动力赛车。真实物理驾驶录制后，以正常速度在 Godot 中实时重放；新增精简遥测 HUD，并在结束后展示本次播放帧率。</p>
<div class="stats"><div class="stat"><b>75.000 秒</b><span>1280×720 · 60 FPS · 4,500 帧</span></div><div class="stat"><b>15.4° → &lt;4°</b><span>连续救车镜头 · 稳定约 5 秒</span></div><div class="stat"><b>110 km/h</b><span>实测最高车速 · 1× 播放</span></div><div class="stat"><b>3.03 秒</b><span>动物完全离开后的保守安全间隔</span></div></div>
<video id="film" controls playsinline preload="metadata" poster="previews/01-establish.jpg" src="demo-75s.mp4"></video><p class="links"><a href="demo-75s.mp4">原版纯电影录像</a><a href="side.mp4">5 秒侧拍短片</a><a href="recovery.mp4">12 秒连续救车短片</a><a href="README.md">实现与复现说明</a><a href="validation/metrics.json">原始验收指标</a></p><p class="muted">点击任意分镜预览，可在完整影片中跳转到该镜头。</p><h2>新版遥测 HUD</h2><p>暖白赛车数字、橙色提示、深色斜切面板。左下为车身侧滑与横纵 G，右下为车速、挡位、转速和原厂全油门扭矩曲线。曲线值不是当前实际输出扭矩；未录制的逐轮受力不作伪造展示。</p><video controls playsinline preload="metadata" poster="previews/04-recovery.jpg" src="telemetry-recovery.mp4"></video><p class="muted">上方 75 秒原版保留纯电影画面；此 12 秒短片与下方预览展示新版游戏内 HUD。G 由真实录制轨迹计算，仪表随同一回放时刻暂停和重播。</p><h2>结束页 · 实际播放性能</h2><img style="width:100%;border-radius:12px" src="validation/performance-1280.jpg" alt="实际播放结束页与帧率曲线"><p>平均值按总帧数 / 有效播放时间计算；最高、最低为单帧瞬时 FPS，曲线每 0.5 秒汇总。加载与暂停不计入，固定帧率导出不冒充性能结果。<a href="validation/playback-performance.json">本机原始记录</a> · <a href="validation/performance-1920.jpg">1080p 结束页</a></p><h2>12 镜时间轴</h2><div class="grid">'''+''.join(cards)+'''</div>
<h2>验收记录</h2><p class="note">镜头角度与位置为统一回放时刻的确定函数；普通驾驶、回放和输入控制器在 Demo 世界内停用。暂停保留画面与事件时刻，“再看一次”直接复用三个已准备好的场景。</p><details><summary>驾驶与实际速度</summary><p>120 Hz 原厂车辆物理，60 Hz 姿态与遥测采样。R200 救车配置只存在于录制进程：ABS 开启，ESP 与牵引力控制关闭；无手刹、无镜内复位。首段素材保留起步预热，电影时间轴从行驶片段切入。弯前真实制动会短暂低于分镜巡航目标，例如侧拍最低 55.6 km/h；没有通过加速播放补偿。</p><div class="table-wrap"><table><thead><tr><th>时间</th><th>镜头</th><th>最低 km/h</th><th>中位 km/h</th><th>最高 km/h</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div></details>
<details><summary>稳定性、事件与流程</summary><p>本次专项测试 95 项、仪表与帧率计算 13 项、HUD / 调试面板 / 菜单输入回归 105 项通过；原版既有相机、幽灵存档、回放相册、检查点、输入与电影转场相关回归共 149 项通过。侧拍、救车与引擎盖均检查 30 / 60 / 120 FPS 采样与原生渲染；镜头位置和旋转连续，固定拍摄侧。全场景车身包络扫描未发现景物碰撞。驯鹿横穿、河桥关系和直升机同框通过逐帧原生画面检查，至少连续 2 秒可辨。</p><p>空格 / Esc / 手柄 Start 暂停继续；暂停菜单提供继续、重播、返回。模拟键盘与手柄输入通过；未将模拟验证声称为实体手柄验证。已检查 1280×720、1920×1080 的暂停和结束页。玩家档案、成绩、解锁与设置未改变。</p><p>MovieWriter 的固定帧率用于检查帧序列和时间一致性，不代表所有设备都能实时运行至 120 FPS。正式导出包已从独立空目录读取检查，分镜清单和七段录制均完整打包。</p><p><a href="validation/showcase_test.log">专项测试日志</a> · <a href="validation/captures.json">原生录制记录</a> · <a href="validation/pause-1920.jpg">暂停页</a> · <a href="validation/end-1920.jpg">结束页</a></p></details>
<details><summary>实现边界</summary><p>未修改普通幽灵格式与玩家存档格式。Demo 扩展遥测与 manifest 放在 resources/showcase；实时渲染使用七份已录制素材，安装包不依赖此文档中的 MP4。原始物理录制使用道路碰撞世界，交付片段另外经过完整场景碰撞扫描。各镜头都是精选片段，跨镜头的路程并非一条连续比赛记录。</p><p>影片中的速度为真实物理速度，镜头切换也包含素材切换。15–25° 是救车峰值目标，实际峰值 15.39°；没有把 12 秒整镜描述成持续大角度漂移。</p></details><footer>全部预览来自实际 Godot 渲染。完整版和短片均保留同步音轨。光柱：松岭冰青 / 海岸淡紫 / 高地琥珀金。</footer></main><script>document.querySelectorAll('[data-seek]').forEach(b=>b.addEventListener('click',()=>{const v=document.getElementById('film');v.currentTime=Number(b.dataset.seek);v.play();v.scrollIntoView({behavior:'smooth',block:'center'})}));</script></html>'''
(out/'index.html').write_text(page)
